{
    std::mt19937_64 rng(0x0006abcd);
    for (unsigned i=0; i<12000; ++i) {
        auto a=MakeCP(Random256(rng),Random256(rng));
        auto b=MakeCP(Random256(rng),Random256(rng));
        const int expected=OracleLt(a.chainWork,a.chainStake,b.chainWork,b.chainStake) ? -1 :
            (OracleEq(a.chainWork,a.chainStake,b.chainWork,b.chainStake) ? 0 : 1);
        ASSERT_EQ(expected,CompareChainPower(a,b));
    }
}
TEST_F(ChainPowerExact, FusedTreeInterleavedHistory)
{
    // All three sets share the SAME live objects, hashes, and addresses.
    std::vector<CBlockIndex> blocks(192);
    std::vector<uint256> hashes(blocks.size());
    std::mt19937_64 rng(0x0006beef);
    for (size_t i=0;i<blocks.size();++i) {
        hashes[i]=ArithToUint256(arith_uint256(i+1));
        blocks[i].phashBlock=&hashes[i];
        blocks[i].chainPower=MakeCP(WithBits(64+(i%192),rng),WithBits(32+(i%210),rng));
        blocks[i].nSequenceId=i%7;
    }
    // The exact pointer-ordered audit fixture A<C, C<B, B<A.
    blocks[0].chainPower=MakeCP(arith_uint256(1000000),arith_uint256(1000000));
    blocks[1].chainPower=MakeCP(arith_uint256(999999),arith_uint256(1000002));
    blocks[2].chainPower=MakeCP(arith_uint256(1000001),arith_uint256(1000001));
    for (int i=0;i<3;++i) blocks[i].nSequenceId=0;
    ASSERT_TRUE(FusedTreeComparator()(&blocks[0],&blocks[2]));
    ASSERT_TRUE(FusedTreeComparator()(&blocks[2],&blocks[1]));
    ASSERT_TRUE(FusedTreeComparator()(&blocks[1],&blocks[0]));
    // Equal and rounded-power ties, distinct sequence IDs and pointer ties.
    for (int i=3;i<16;++i) blocks[i].chainPower=blocks[0].chainPower;
    std::set<CBlockIndex*,LegacyTreeComparator> old;
    std::set<CBlockIndex*,FusedTreeComparator> fused;
    std::set<CBlockIndex*,LiteralTreeComparator> literal;
    auto check=[&]() {
        ASSERT_EQ(old.size(),fused.size()); ASSERT_EQ(old.size(),literal.size());
        std::vector<CBlockIndex*> a(old.begin(),old.end()),b(fused.begin(),fused.end()),c(literal.begin(),literal.end());
        ASSERT_EQ(a,b); ASSERT_EQ(a,c);
        for(size_t j=0;j<a.size();++j) ASSERT_EQ(a[j]->GetBlockHash(),b[j]->GetBlockHash());
        if(!old.empty()) { ASSERT_EQ(*old.rbegin(),*fused.rbegin()); ASSERT_EQ(*old.rbegin(),*literal.rbegin()); }
    };
    auto insert=[&](CBlockIndex *p) {
        bool a=old.insert(p).second,b=fused.insert(p).second,c=literal.insert(p).second;
        ASSERT_EQ(a,b); ASSERT_EQ(a,c); check();
    };
    for(unsigned i=0;i<48;++i) insert(&blocks[i]);
    for(unsigned step=0;step<720;++step) {
        SCOPED_TRACE(step);
        CBlockIndex *p=&blocks[rng()%blocks.size()];
        switch(step%6) {
        case 0: case 1: insert(p); break;
        case 2: {
            auto a=old.find(p),b=fused.find(p),c=literal.find(p);
            ASSERT_EQ(a==old.end(),b==fused.end()); ASSERT_EQ(a==old.end(),c==literal.end());
            if(a!=old.end()) { ASSERT_EQ(*a,*b); ASSERT_EQ(*a,*c); }
            break;
        }
        case 3: {
            const size_t a=old.erase(p),b=fused.erase(p),c=literal.erase(p);
            ASSERT_EQ(a,b); ASSERT_EQ(a,c); break;
        }
        case 4: {
            // Match rewind's sequence reset BEFORE key erasure, even though
            // this mutates a comparator key. Do not silently use iterator erase.
            p->nSequenceId=0; check();
            const size_t a=old.erase(p),b=fused.erase(p),c=literal.erase(p);
            ASSERT_EQ(a,b); ASSERT_EQ(a,c); break;
        }
        case 5:
            // Prefix pruning, preserving the exact operation history.
            for(unsigned j=0;j<3 && !old.empty();++j) {
                ASSERT_EQ(*old.begin(),*fused.begin()); ASSERT_EQ(*old.begin(),*literal.begin());
                old.erase(old.begin()); fused.erase(fused.begin()); literal.erase(literal.begin()); check();
            }
            break;
        }
        check();
    }
}

